const README_APPEND = "\n\n## Plus Bridge (this fork)\n\nThis fork keeps the upstream Windows app, executor, permissions, session timeline, Compact & Resume, desktop helper and worker broker, and adds a **loopback-only browser-extension transport** for personal ChatGPT accounts that do not expose writable custom MCP apps.\n\n1. Install/build the app exactly like upstream and load the bundled unpacked Chrome extension.\n2. Open ChatGPT on the web. A small **Enable local tools** control appears near the composer when the local app is reachable.\n3. Press it once in a chat. The extension gives that chat the local tool protocol. Tool requests are executed by the app on `127.0.0.1` and the result is fed back into the same conversation; transport turns are hidden by the extension.\n\nThis does **not** unlock restricted OpenAI features, raise plan/rate limits, or bypass confirmations/safety controls. It only changes how the already-local executor is reached. The local permission panel remains authoritative.\n";
const SECURITY_APPEND = "\n\n## Plus Bridge transport\n\nThe Plus Bridge listens only on `127.0.0.1:8775-8779`. Discovery exposes no credential. Pairing and authenticated tool routes require a Chrome-extension origin; a random process-lifetime bearer token stays in the extension service worker and is never exposed to the ChatGPT page/content script. Calls are idempotency-cached by conversation + call id so a page reload does not repeat a destructive local action. The same upstream capability/read-only checks still gate filesystem, command and desktop operations.\n";

async function write(relative, content) {
  const target = path.join(process.cwd(), relative);
  await fs.mkdir(path.dirname(target), { recursive: true });
  await fs.writeFile(target, content, 'utf8');
}

function replaceOnce(text, from, to, label) {
  if (text.includes(to)) return text;
  const at = text.indexOf(from);
  if (at === -1) throw new Error(`Could not patch ${label}: anchor not found`);
  return text.slice(0, at) + to + text.slice(at + from.length);
}

for (const [relative, content] of Object.entries(files)) await write(relative, content);

{
  const file = 'src/main/mcp/tools-core.ts';
  let text = await fs.readFile(file, 'utf8');
  text = replaceOnce(text, 'interface ParsedPatchRun {', 'export interface ParsedPatchRun {', `${file} ParsedPatchRun`);
  text = replaceOnce(text, 'async function runParsedPatch(\n', 'export async function runParsedPatch(\n', `${file} runParsedPatch`);
  await fs.writeFile(file, text, 'utf8');
}

{
  const file = 'src/main/index.ts';
  let text = await fs.readFile(file, 'utf8');
  text = replaceOnce(
    text,
    "import { setBrowserOpener, startBridge, stopBridge } from './bridge.js';",
    "import { setBrowserOpener, startBridge, stopBridge } from './bridge.js';\nimport { startPlusBridge, stopPlusBridge } from './plus/bridge.js';",
    `${file} import`
  );
  text = replaceOnce(
    text,
    "  logInfo('app started');",
    "  logInfo('app started');\n\n  // Plus accounts do not get a writable custom MCP surface. The companion extension can\n  // instead use this loopback-only transport; it preserves the same local executor and\n  // permission boundary without claiming to unlock any server-side OpenAI feature.\n  void startPlusBridge().catch((err: Error) => logError(`Plus Bridge failed to start: ${err.message}`));",
    `${file} startup`
  );
  text = replaceOnce(
    text,
    "    await runPhase('admission/drain', [disconnect(), stopBridge()]);",
    "    await runPhase('admission/drain', [disconnect(), stopBridge(), stopPlusBridge()]);",
    `${file} shutdown`
  );
  await fs.writeFile(file, text, 'utf8');
}

{
  const file = 'extension/manifest.json';
  const manifest = JSON.parse(await fs.readFile(file, 'utf8'));
  manifest.background.service_worker = 'background-entry.js';
  const hosts = new Set(manifest.host_permissions || []);
  for (let port = 8775; port <= 8779; port++) hosts.add(`http://127.0.0.1:${port}/*`);
  manifest.host_permissions = [...hosts];
  const mainScript = (manifest.content_scripts || []).find((entry) => Array.isArray(entry.js) && entry.js.includes('content.js'));
  if (!mainScript) throw new Error('Could not find the main ChatGPT content-script entry');
  if (!mainScript.js.includes('plus-content.js')) mainScript.js.push('plus-content.js');
  mainScript.css ||= [];
  if (!mainScript.css.includes('plus.css')) mainScript.css.push('plus.css');
  await fs.writeFile(file, JSON.stringify(manifest, null, 2) + '\n', 'utf8');
}

{
  const file = 'README.md';
  let text = await fs.readFile(file, 'utf8');
  if (!text.includes('## Plus Bridge (this fork)')) {
    text += README_APPEND;
    await fs.writeFile(file, text, 'utf8');
  }
}

{
  const file = 'SECURITY.md';
  let text = await fs.readFile(file, 'utf8');
  if (!text.includes('## Plus Bridge transport')) {
    text += SECURITY_APPEND;
    await fs.writeFile(file, text, 'utf8');
  }
}

{
  const file = 'package.json';
  const pkg = JSON.parse(await fs.readFile(file, 'utf8'));
  pkg.description = 'Chat On Steroids with a loopback Plus Bridge transport for the normal ChatGPT web UI.';
  await fs.writeFile(file, JSON.stringify(pkg, null, 2) + '\n', 'utf8');
}

